<template><div class="login"><div class="card"><div class="mark">🍏</div><span class="kicker">FRESH FRUIT CURATOR</span><h1>鲜果铺</h1><p>经营管理后台</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" size="large" autocomplete="username" placeholder="管理员账号"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" autocomplete="current-password" show-password placeholder="密码" @keyup.enter="submit"/></el-form-item><el-button class="btn" type="primary" size="large" :loading="loading" @click="submit">登录后台</el-button></el-form><small>初始登录信息见 README，上线前请更换强密码</small></div></div></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{api}from'../api';const router=useRouter(),loading=ref(false),form=reactive({username:'admin',password:''});async function submit(){if(!form.username.trim()||!form.password)return ElMessage.warning('请输入账号和密码');loading.value=true;try{const d:any=await api.post('/auth/admin/login',form);localStorage.setItem('admin_token',d.token);router.push('/dashboard')}catch(e:any){ElMessage.error(e.response?.data?.message||'登录失败')}finally{loading.value=false}}</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 25% 15%,#dcebdc,transparent 34%),radial-gradient(circle at 80% 85%,#eee5cf,transparent 30%),#f6f4ed}.card{width:400px;padding:42px 44px;border:1px solid #e5e2d8;border-radius:24px;background:#fffdf8;box-shadow:0 24px 70px rgba(25,62,44,.11);text-align:center}.mark{width:68px;height:68px;margin:0 auto 15px;border-radius:21px;background:#e4eee3;display:grid;place-items:center;font-size:38px}.kicker{color:#718b7b;font-size:9px;letter-spacing:3px}.card h1{margin:8px 0 0;font-size:28px}.card p{color:#929a94;margin:7px 0 29px}.btn{width:100%}.card small{display:block;color:#a3aaa5;margin-top:20px;font-size:11px}</style>
